-- Wiki image cache 1/6 (epic #226, issue #227): the state table of the OSRS
-- Wiki image cache. Expand phase only, compatible with the previous app
-- version (rolling the app image back is safe; the database is not reverted):
-- one new table that nothing in the previous app version reads or writes.
--
-- Generated by drizzle-kit, then edited by hand: the CHECK constraint is added
-- by hand (drizzle-kit 0.24 does not emit CHECKs); CREATE TABLE IF NOT EXISTS
-- and the guarded constraint make a re-run a no-op.

CREATE TABLE IF NOT EXISTS "bingoscape-next_osrs_image_cache" (
	"key" text PRIMARY KEY NOT NULL,
	"status" text NOT NULL,
	"file_name" text,
	"content_type" varchar(100),
	"bytes" integer,
	"etag" text,
	"last_modified" text,
	"fetched_at" timestamp with time zone,
	"refreshed_at" timestamp with time zone,
	"attempts" integer DEFAULT 0 NOT NULL,
	"retry_after" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
DO $$ BEGIN
 ALTER TABLE "bingoscape-next_osrs_image_cache" ADD CONSTRAINT "osrs_image_cache_status_check" CHECK ("status" IN ('ok', 'not_found', 'error'));
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;
